diff --git a/scripts/check_run.sh b/scripts/check_run.sh
index 0197d34..f5dd4dd 100644
--- a/scripts/check_run.sh
+++ b/scripts/check_run.sh
@@ -3,12 +3,18 @@ set -euo pipefail
 action=$1
 shift
 head_sha_for() {
-  gh api "repos/$GITHUB_REPOSITORY/pulls/$1" -q .head.sha
+  local sha
+  sha=$(gh api "repos/$GITHUB_REPOSITORY/pulls/$1" -q .head.sha)
+  if [ -z "$sha" ]; then
+    echo "error: no head SHA found for PR $1 in $GITHUB_REPOSITORY" >&2
+    exit 1
+  fi
+  echo "$sha"
 }
 case "$action" in
   open) gh api "repos/$GITHUB_REPOSITORY/check-runs" -f name=ai-review -f head_sha="$1" -f status=in_progress ;;
-  open-for-pr) gh api "repos/$GITHUB_REPOSITORY/check-runs" -f name=ai-review -f head_sha="$(head_sha_for "$1")" -f status=in_progress ;;
+  open-for-pr) sha=$(head_sha_for "$1"); gh api "repos/$GITHUB_REPOSITORY/check-runs" -f name=ai-review -f head_sha="$sha" -f status=in_progress ;;
   complete) gh api "repos/$GITHUB_REPOSITORY/check-runs" -f name=ai-review -f head_sha="$1" -f status=completed -f conclusion="$2" ;;
-  complete-for-pr) gh api "repos/$GITHUB_REPOSITORY/check-runs" -f name=ai-review -f head_sha="$(head_sha_for "$1")" -f status=completed -f conclusion="$2" ;;
+  complete-for-pr) sha=$(head_sha_for "$1"); gh api "repos/$GITHUB_REPOSITORY/check-runs" -f name=ai-review -f head_sha="$sha" -f status=completed -f conclusion="$2" ;;
   *) echo "unknown action $action" >&2; exit 2 ;;
 esac

